#!/usr/bin/env node
// Generates every derived file from data/collection.json.
//   node scripts/build.mjs           write files
//   node scripts/build.mjs --check   exit 1 when a generated file is out of date
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import {
  parseCollection,
  validateCollection,
  renderCollectionMarkdown,
  renderLlmsTxt,
  replaceMarked,
} from "./lib.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SITE_URL = "https://enzovezzaro.github.io/awesome-homebrew-games/";
const REPO_URL = "https://github.com/EnzoVezzaro/awesome-homebrew-games";

const check = process.argv.includes("--check");
const read = (path) => readFileSync(join(ROOT, path), "utf8");

let collection;
try {
  collection = parseCollection(read("data/collection.json"), "data/collection.json");
} catch (error) {
  console.error(error.message);
  process.exit(1);
}
const errors = validateCollection(collection);
if (errors.length > 0) {
  console.error(`data/collection.json has ${errors.length} problem(s):`);
  for (const e of errors) console.error(`  - ${e}`);
  process.exit(1);
}

const count = collection.entries.length;
const badge = `![Entries](https://img.shields.io/badge/entries-${count}-dbff00?style=classic&labelColor=0b0b0b)`;

let readme = read("README.md");
readme = replaceMarked(readme, "count", badge);
readme = replaceMarked(readme, "collection", renderCollectionMarkdown(collection));

const siteData = `// Generated by scripts/build.mjs from data/collection.json. Do not edit.\nwindow.HOMEBREW = ${JSON.stringify(collection)};\n`;

const outputs = {
  "README.md": readme,
  "llms.txt": renderLlmsTxt(collection, { siteUrl: SITE_URL, repoUrl: REPO_URL }),
  "site/llms.txt": renderLlmsTxt(collection, { siteUrl: SITE_URL, repoUrl: REPO_URL }),
  "site/collection.js": siteData,
  "site/collection.json": `${JSON.stringify(collection, null, 2)}\n`,
};

let stale = 0;
for (const [path, next] of Object.entries(outputs)) {
  const current = existsSync(join(ROOT, path)) ? read(path) : null;
  if (current === next) continue;
  if (check) {
    console.error(`stale: ${path}`);
    stale += 1;
  } else {
    writeFileSync(join(ROOT, path), next);
    console.log(`wrote ${path}`);
  }
}

if (check && stale > 0) {
  console.error("Run `npm run build` and commit the result.");
  process.exit(1);
}
if (!check) console.log(`${count} entries, ${collection.categories.length} categories.`);
